const keyTo = (tabs: ReadonlyArray<TabId>, current: TabId, tab: TabId) => {
  const from = tabs.indexOf(current);
  const to = tabs.indexOf(tab);

  if ((from + 1) % tabs.length === to) return next();

  return (to + 1) % tabs.length === from ? previous() : null;
};

